{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted

enum State { PATROL, CHASE, RETURN }


func run() -> String:
	var current_state: State = State.CHASE
	var player_in_sight: bool = false

	if player_in_sight:
		current_state = State.CHASE
	else:
		current_state = State.RETURN

	match current_state:
		State.PATROL:
			return "pattuglia"
		State.CHASE:
			return "insegue"
		State.RETURN:
			return "torna"
	return "sconosciuto"
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "`player_in_sight` è falso, quindi il codice entra nel ramo `else` e imposta `current_state` a `State.RETURN`. Nel blocco `match`, il caso `State.RETURN` restituisce "torna"."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var patrol_index: int = 2
	var total_points: int = 3

	patrol_index += 1
	if patrol_index >= total_points:
		patrol_index = 0

	return patrol_index
",
   "domanda": "Quanto vale `patrol_index` alla fine?",
   "spiegazione": "`patrol_index` parte da 2 e viene incrementato a 3. Poiché 3 non è minore di `total_points` (che è 3), la condizione `patrol_index >= total_points` è vera, quindi l'indice viene riportato a 0."
  },
  {
   "codice": "extends RefCounted


func run() -> bool:
	var enemy_pos := Vector2(0, 0)
	var player_pos := Vector2(30, 40)
	var detection_range: float = 50.0

	var distance_squared: float = enemy_pos.distance_squared_to(player_pos)
	var range_squared: float = detection_range * detection_range

	return distance_squared <= range_squared
",
   "domanda": "Che valore booleano restituisce `run()`?",
   "spiegazione": "La distanza tra (0,0) e (30,40) è 50 (teorema di Pitagora: 30 al quadrato più 40 al quadrato fa 900+1600=2500, la radice è 50). `distance_squared` è 2500. `range_squared` è 50 * 50 = 2500. 2500 <= 2500 è vero."
  },
  {
   "codice": "extends RefCounted


func run() -> Vector2:
	var direction := Vector2(10, 0)
	var speed: float = 2.5
	var velocity = direction.normalized() * speed * 4
	return velocity
",
   "domanda": "Quanto vale `velocity` alla fine?",
   "spiegazione": "`direction` è `Vector2(10, 0)`, normalizzato diventa `Vector2(1, 0)`. Moltiplicato per `speed` (2.5) e poi per 4 fa `Vector2(10, 0)`."
